jQuery(document).ready(function($){function saswpAiSwitchProvider(){var s=$('#saswp_ai_provider').val();$('li:has(.saswp-ai-row.gemini)').toggle(s==='gemini');$('li:has(.saswp-ai-row.openai)').toggle(s==='openai');}$('#saswp_ai_provider').on('change',saswpAiSwitchProvider);saswpAiSwitchProvider();$(document).on('click','.saswp-ai-tab-nav[data-div-id]',function(e){e.preventDefault();var d=$(this).attr('data-div-id');$('.saswp-ai-tab-nav').removeClass('saswp-global-selected');$(this).addClass('saswp-global-selected');$('.saswp-ai-tab-content').addClass('saswp_hide');$('#'+d).removeClass('saswp_hide');});var saswpAiCheckboxMap={'saswp-ai-enable-checkbox':'saswp_ai_enable','saswp-ai-auto-gen-checkbox':'saswp_ai_auto_gen','saswp-ai-overwrite-checkbox':'saswp_ai_overwrite'};function saswpAiSyncCheckbox(c){var id=$(c).attr('id'),hid=saswpAiCheckboxMap[id];if(hid){$('#'+hid).val($(c).is(':checked')?1:0);}}$.each(saswpAiCheckboxMap,function(c){saswpAiSyncCheckbox($('#'+c));});$(document).on('change','#saswp-ai-enable-checkbox,#saswp-ai-auto-gen-checkbox,#saswp-ai-overwrite-checkbox',function(){saswpAiSyncCheckbox(this);});if($('#saswp_ai_gemini_model').length&&!$('#saswp-fetch-gemini-models').length){$('#saswp_ai_gemini_model').after(' <button type="button" id="saswp-fetch-gemini-models" class="button button-secondary saswp-fetch-models-btn" data-provider="gemini" data-key-id="saswp_ai_gemini_key" data-model-id="saswp_ai_gemini_model"><span class="dashicons dashicons-update"></span> Fetch Models</button><span class="saswp-fetch-status" id="saswp-fetch-status-gemini"></span>');}if($('#saswp_ai_openai_model').length&&!$('#saswp-fetch-openai-models').length){$('#saswp_ai_openai_model').after(' <button type="button" id="saswp-fetch-openai-models" class="button button-secondary saswp-fetch-models-btn" data-provider="openai" data-key-id="saswp_ai_openai_key" data-model-id="saswp_ai_openai_model"><span class="dashicons dashicons-update"></span> Fetch Models</button><span class="saswp-fetch-status" id="saswp-fetch-status-openai"></span>');}$(document).on('click','.saswp-fetch-models-btn',function(e){e.preventDefault();var btn=$(this),provider=btn.attr('data-provider'),keyId=btn.attr('data-key-id'),modelId=btn.attr('data-model-id'),apiKey=$('#'+keyId).val(),statusEl=$('#saswp-fetch-status-'+provider);if(!apiKey){statusEl.css('color','#d63638').text('Please enter an API Key first.');return;}btn.prop('disabled',true);statusEl.css('color','#666').text('Fetching models from API...');$.ajax({url:saswp_ai_settings_params.ajax_url,type:'POST',data:{action:'saswp_fetch_ai_models',saswp_security_nonce:saswp_ai_settings_params.nonce,provider:provider,api_key:apiKey},success:function(r){btn.prop('disabled',false);if(r.success&&r.data.models){var ms=$('#'+modelId),cv=ms.val();ms.empty();$.each(r.data.models,function(i,m){ms.append($('<option>',{value:m.id,text:m.name}));});if(cv&&ms.find('option[value="'+cv+'"]').length){ms.val(cv);}statusEl.css('color','#00a32a').text('Successfully loaded '+r.data.models.length+' models!');}else{var err=(r.data&&r.data.error)?r.data.error:'Failed to fetch models.';statusEl.css('color','#d63638').text(err);}},error:function(){btn.prop('disabled',false);statusEl.css('color','#d63638').text('Network error while fetching models.');}});});});
